const cfg = $('Settings').first().json;
if (!cfg.slackChannelId || cfg.slackChannelId.startsWith('YOUR_')) throw new Error('Set slackChannelId in Settings.');
const events = $('New Folderit file').all();
const seen = new Set();
const escape = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const out = [];
for (const [i, item] of $input.all().entries()) {
  const event = events[i]?.json;
  if (!event?.auditUid || !event.entityUid || event.entityUid !== item.json.uid) throw new Error('Document and audit event do not match. Inspect this execution.');
  if (seen.has(event.auditUid)) continue;
  seen.add(event.auditUid);
  if (cfg.folderUid && item.json.folderUid !== cfg.folderUid) continue;
  out.push({json: {auditUid: event.auditUid, fileUid: item.json.uid, fileName: item.json.name, slackChannelId: cfg.slackChannelId, text: `New document in Folderit: ${escape(item.json.name)}\nDocument UID: ${escape(item.json.uid)}\nAudit UID: ${escape(event.auditUid)}`}, pairedItem: {item: i}});
}
return out;
